input.command:
# Check multiple possible desktop locations
$paths = @(
    "$env:USERPROFILE\Desktop\move-claude-to-e.ps1",
    "$env:USERPROFILE\OneDrive\Desktop\move-claude-to-e.ps1",
    "$env:PUBLIC\Desktop\move-claude-to-e.ps1"
)
foreach ($p in $paths) {
    if (Test-Path $p) { Write-Host "FOUND: $p" }
    else              { Write-Host "NOT:   $p" }
}

# Also check actual desktop folder by registry
$desktop = [Environment]::GetFolderPath("Desktop")
Write-Host ""
Write-Host "System desktop path: $desktop"
$fileAtDesktop = Join-Path $desktop "move-claude-to-e.ps1"
if (Test-Path $fileAtDesktop) {
    Write-Host "File exists at system desktop: $fileAtDesktop"
    Write-Host "Size: $((Get-Item $fileAtDesktop).Length) bytes"
} else {
    Write-Host "File NOT at system desktop path"
}
